with account_summary as (select account_id, max(amount) - min(amount) amount_range, round((100 * sum(case when txn_type = 'REFUND' then 1 else 0 end)) / count(*), 1) pct_refund from transactions where merchant is null group by account_id) select a.id, a.status, a.customer_id, as.amount_range, as.pct_refund from accounts a join account_summary as on a.id = as.account_id order by status, id limit 10
